import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"CLI Reference","description":"Every s3dbbackup command with syntax, example output, and when to use it.","frontmatter":{"title":"CLI Reference","description":"Every s3dbbackup command with syntax, example output, and when to use it."},"headers":[],"relativePath":"s3-database-storage-for-vps/user-guide/cli.md","filePath":"s3-database-storage-for-vps/user-guide/cli.md","lastUpdated":1782847089000}'),n={name:"s3-database-storage-for-vps/user-guide/cli.md"};function p(l,s,d,o,c,r){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>All commands are run as <strong>root</strong> (they read <code>/etc/s3dbbackup/config.json</code> and may write systemd units and local backups).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s3dbbackup &lt;command&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#setup"><code>setup</code></a></td><td>Interactive first-time setup wizard</td></tr><tr><td><a href="#backup"><code>backup</code></a></td><td>Run a backup now (also called by the systemd timer)</td></tr><tr><td><a href="#extract"><code>extract</code></a></td><td>Browse S3 backups and download one</td></tr><tr><td><a href="#status"><code>status</code></a></td><td>Show config, last run, and next scheduled run</td></tr><tr><td><a href="#version"><code>version</code></a></td><td>Print the version</td></tr></tbody></table><h2 id="setup" tabindex="-1"><code>setup</code> <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;\`setup\`&quot;">​</a></h2><p>Runs the interactive wizard: S3 connection, folder, connection test, database selection, local copy, frequency, retention, Discord alerts, then installs the systemd timer.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>Use it the first time, or any time you want to change what is backed up, how often, retention, or notifications.</p><h2 id="backup" tabindex="-1"><code>backup</code> <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;\`backup\`&quot;">​</a></h2><p>Runs one full backup cycle immediately: dumps each configured database, uploads to S3, keeps a local copy, enforces retention, and sends notifications. This is exactly what the systemd timer invokes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[*] Backup started for 2 database(s) at 2026-06-30_18-00-01</span></span>
<span class="line"><span>  - Dumping postgresql/app_production ...</span></span>
<span class="line"><span>    Uploading to s3://.../s3dbbackup/postgresql/app_production/2026-06-30_18-00-01.sql.gz (12.84 MiB)</span></span>
<span class="line"><span>    Retention removed s3://.../s3dbbackup/postgresql/app_production/2026-06-23_18-00-01.sql.gz</span></span>
<span class="line"><span>    [OK] app_production</span></span>
<span class="line"><span>  - Dumping mysql/wordpress ...</span></span>
<span class="line"><span>    Uploading to s3://.../s3dbbackup/mysql/wordpress/2026-06-30_18-00-02.sql.gz (3.21 MiB)</span></span>
<span class="line"><span>    [OK] wordpress</span></span>
<span class="line"><span>[*] Backup finished. 2 ok, 0 failed.</span></span></code></pre></div><p>Exit code is <code>0</code> when every database succeeded, <code>1</code> if any failed.</p><h2 id="extract" tabindex="-1"><code>extract</code> <a class="header-anchor" href="#extract" aria-label="Permalink to &quot;\`extract\`&quot;">​</a></h2><p>Opens the interactive extractor — connect to S3, browse a tree of every stored backup, pick one, and download it (optionally decompressing). See <a href="/pingless-studios-docs/s3-database-storage-for-vps/user-guide/extractor">The Extractor</a> for a full walkthrough.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract</span></span></code></pre></div><h2 id="status" tabindex="-1"><code>status</code> <a class="header-anchor" href="#status" aria-label="Permalink to &quot;\`status\`&quot;">​</a></h2><p>Prints your configuration, the last run result, and the next scheduled run.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>╭──────────── S3 DB Backup — Configuration ────────────╮</span></span>
<span class="line"><span>│ Endpoint         https://&lt;id&gt;.r2.cloudflarestorage.com │</span></span>
<span class="line"><span>│ Bucket / folder  my-vps-backups/s3dbbackup             │</span></span>
<span class="line"><span>│ Region           auto                                  │</span></span>
<span class="line"><span>│ Databases        postgresql:app_production, mysql:wordpress │</span></span>
<span class="line"><span>│ Schedule         Every day (midnight)                  │</span></span>
<span class="line"><span>│ Max copies       7                                     │</span></span>
<span class="line"><span>│ Local copy       /var/backups/s3dbbackup               │</span></span>
<span class="line"><span>│ Notifications    on: trigger,success,failure,error     │</span></span>
<span class="line"><span>╰────────────────────────────────────────────────────────╯</span></span>
<span class="line"><span>Last run: 2026-06-30T18:00:03  (failures: 0)</span></span></code></pre></div><h2 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;\`version\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># s3dbbackup 1.0.0</span></span></code></pre></div><h2 id="running-on-a-schedule" tabindex="-1">Running on a schedule <a class="header-anchor" href="#running-on-a-schedule" aria-label="Permalink to &quot;Running on a schedule&quot;">​</a></h2><p>The wizard installs a systemd timer, but you can manage it directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-timers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.timer</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # when does it run next?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.timer</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # is it active?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # run logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup.service</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # trigger a run via systemd</span></span></code></pre></div>`,27)])])}const k=a(n,[["render",p]]);export{u as __pageData,k as default};
